import { formatDate } from './dateFormat';

/**
 * The line at the foot of a PDF report, the same from the Worker (worker/src/pdf.ts) and from the
 * browser (frontend/src/core/storage/clientPdfReports.ts): "Generated by Token Circles on 4 Nov
 * 2026". `day` is the reader's today, a 'YYYY-MM-DD' or a Date read on the local calendar.
 */
export function reportFooter(day: unknown): string {
  return `Generated by Token Circles on ${formatDate(day)}`;
}
